INSERT INTO public.maint_task_library VALUES (1, 'MNT-PNP-001', 'mounter', '吸嘴清洁与检查', 'Nozzle Cleaning & Inspection', 'shift', 20, 'operator', false, true, '使用超声波清洗吸嘴，检查吸嘴表面有无无锡渣、变形或堵塞', 'Clean nozzles in ultrasonic bath; inspect for solder residue, deformation, blockage', '超声波清洗机, 40x显微镜', '吸嘴 (Nozzle)', '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
INSERT INTO public.maint_task_library VALUES (2, 'MNT-PNP-002', 'mounter', '气压/真空度检查', 'Air Pressure & Vacuum Check', 'shift', 10, 'operator', true, true, '检查气压是否在0.5-0.7MPa范围，真空度是否正常', 'Check air pressure 0.5-0.7MPa, verify vacuum level', '气压表, 真空表', NULL, '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
INSERT INTO public.maint_task_library VALUES (3, 'MNT-PNP-003', 'mounter', 'feeder供料器检查', 'Feeder Check', 'shift', 15, 'operator', false, false, '检查料带是否正常推进，有无歪斜或卡料', 'Verify tape feeding smoothly, no skew or jam', NULL, 'feeder弹簧', '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
INSERT INTO public.maint_task_library VALUES (4, 'MNT-PNP-004', 'mounter', '贴装头运行状态听声检查', 'Mounting Head Sound Check', 'shift', 10, 'operator', true, true, '听贴装头运行声音，辨别有无异响或异常振动', 'Listen for abnormal noise or vibration from mount head', NULL, NULL, '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
INSERT INTO public.maint_task_library VALUES (5, 'MNT-PNP-005', 'mounter', '轨道清洁', 'Track Cleaning', 'daily', 15, 'operator', false, false, '清洁导轨上的锡渣、灰尘和杂物', 'Clean solder residue, dust from tracks', '无尘布, 酒精', NULL, '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
INSERT INTO public.maint_task_library VALUES (6, 'MNT-PNP-006', 'mounter', '相机光源检查', 'Camera & Light Source Check', 'daily', 10, 'operator', false, true, '检查光源亮度是否正常，有无闪烁', 'Verify light source brightness, check for flickering', NULL, '光源灯泡', '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
INSERT INTO public.maint_task_library VALUES (7, 'MNT-PNP-007', 'mounter', '安全门联锁测试', 'Safety Interlock Test', 'daily', 5, 'operator', true, true, '测试安全门开门是否立即停机，关门能否复位', 'Test safety door: opens → emergency stop, closes → reset', NULL, NULL, '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
INSERT INTO public.maint_task_library VALUES (8, 'MNT-PNP-008', 'mounter', '丝杠润滑检查', 'Ball Screw Lubrication Check', 'weekly', 20, 'technician', false, true, '检查丝杠润滑脂状况，有无干摩擦', 'Check ball screw lubrication grease condition', '润滑脂枪', '润滑脂', '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
INSERT INTO public.maint_task_library VALUES (9, 'MNT-PNP-009', 'mounter', '皮带张力检查', 'Belt Tension Check', 'weekly', 15, 'technician', false, false, '检查传动皮带张力，有无明显松弛或磨损', 'Check belt tension and wear', NULL, '皮带', '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
INSERT INTO public.maint_task_library VALUES (10, 'MNT-PNP-010', 'mounter', '贴装精度校验', 'Placement Accuracy Calibration', 'weekly', 45, 'technician', false, true, '运行精度测试程序，验证偏移≤0.05mm', 'Run accuracy test: placement offset ≤ 0.05mm', '精度测试板', NULL, '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
INSERT INTO public.maint_task_library VALUES (11, 'MNT-PNP-011', 'mounter', '吸取位置教正', 'Pick-up Position Teaching', 'weekly', 30, 'technician', false, true, '测试吸取教正，确认吸取成功率≥99.5%', 'Test pickup teaching, success rate ≥ 99.5%', NULL, NULL, '2026-11-17 15:55:10.843042+07') ON CONFLICT DO NOTHING;
